{"command": "cat > /tmp/mitm.py <<'EOF'
import socket, threading, sys, time, os

UP = ('127.0.0.2', 7835)
LPORT = 7835
out = open('/tmp/wire.log','w', buffering=1)

def ts():
    return "%.6f" % (time.time()%1000)

def pipe(src, dst, tag):
    try:
        while True:
            d = src.recv(65536)
            if not d:
                out.write(f"[{ts()}] {tag} EOF\n"); break
            out.write(f"[{ts()}] {tag} {len(d)} bytes: {d!r}\n")
            dst.sendall(d)
    except Exception as e:
        out.write(f"[{ts()}] {tag} ERR {e}\n")
    try: dst.shutdown(socket.SHUT_WR)
    except Exception: pass
    try: src.close()
    except Exception: pass
    try: dst.close()
    except Exception: pass

def handle(c, addr):
    out.write(f"[{ts()}] NEW conn from {addr}\n")
    s = socket.socket(); s.connect(UP)
    out.write(f"[{ts()}] connected upstream\n")
    threading.Thread(target=pipe, args=(c,s,'C->S'), daemon=True).start()
    threading.Thread(target=pipe, args=(s,c,'S->C'), daemon=True).start()

ls = socket.socket(); ls.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR,1)
ls.bind(('127.0.0.1', LPORT)); ls.listen(50)
print("mitm up", flush=True)
while True:
    c,a = ls.accept(); threading.Thread(target=handle, args=(c,a), daemon=True).start()
EOF
cd /workspace && for p in $(pgrep -x executable); do kill -9 $p; done; sleep 0.3
setsid nohup ./executable server --min-port 22000 --max-port 22010 --bind-addr 127.0.0.2 --secret sec1 > /tmp/sv.log 2>&1 & sleep 0.6
cat /proc/net/tcp | awk 'NR>1{print $2,$4}'
setsid nohup python3 /tmp/mitm.py > /tmp/mitm.log 2>&1 & sleep 0.5
cat /tmp/mitm.log; cat /proc/net/tcp | awk 'NR>1{print $2,$4}'"}

