{"command": "cd /tmp && python3 - <<'EOF'
import hashlib, hmac, uuid, itertools, string
c,s,t='e13b3b9d-1dd6-4554-b79f-b25fca7716c5','sec1','402e5e51f5ee1fbfd41f753dc9d158f115d0e9aacd913b4a3873d9b1c2a5e984'
cb=uuid.UUID(c).bytes; sb=s.encode()
chal_encs = {
 'str': c.encode(), 'bytes': cb, 'hex32': cb.hex().encode(), 'HEX32': cb.hex().upper().encode(),
 'json': ('{"Challenge":"%s"}'%c).encode(), 'nodash': c.replace('-','').encode(),
}
salt_encs = {'none': b'', 'sb': sb, 'sha_sb': hashlib.sha256(sb).digest(), 'sha_sb_h': hashlib.sha256(sb).hexdigest().encode(),
  'json_sec': ('{"Secret":"%s"}'%s).encode(), 's_json': ('%s'%s).encode()}
hashes = {'sha256':hashlib.sha256,'sha3_256':hashlib.sha3_256,'blake2s':hashlib.blake2s,'sha512_256':None}
def try_all():
    found=[]
    for ce_name, ce in chal_encs.items():
        for se_name, se in salt_encs.items():
            for order in (ce+se, se+ce):
                for hname, h in list(hashes.items()):
                    if h is None: continue
                    if h(order).hexdigest()==t: found.append((ce_name,se_name,'order',hname))
    # hmac
    for ce_name, ce in chal_encs.items():
        for se_name, se in salt_encs.items():
            for hn,h in [('sha256',hashlib.sha256),('sha3_256',hashlib.sha3_256),('blake2s',hashlib.blake2s)]:
                if hmac.new(se, ce, h).hexdigest()==t: found.append((ce_name,se_name,'hmac',hn))
                if hmac.new(ce, se, h).hexdigest()==t: found.append((ce_name,se_name,'hmac_rev',hn))
    return found
print(try_all())
# maybe the secret is hashed together as sha256(challenge_str) but the client uses the *hex digest* of sha256(secret) as key with hmac -> tried
# try sha256 with prefix strings
for pre in ['bore','bore_cli','','\x00','sec1','Challenge']:
    for ce_name, ce in chal_encs.items():
        v = pre.encode()+ce+sb
        if hashlib.sha256(v).hexdigest()==t: print("FOUND prefix", pre, ce_name)
# maybe client uses sha256 over uuid bytes of challenge then hex of digest then + secret, and hashes again
for ce_name, ce in chal_encs.items():
    x = hashlib.sha256(ce).digest()
    if hashlib.sha256(x+sb).hexdigest()==t: print("FOUND double", ce_name)
    if hashlib.sha256(sb+x).hexdigest()==t: print("FOUND double rev", ce_name)
    xh = hashlib.sha256(ce).hexdigest().encode()
    if hashlib.sha256(xh+sb).hexdigest()==t: print("FOUND double hex", ce_name)
    if hashlib.sha256(sb+xh).hexdigest()==t: print("FOUND double hex rev", ce_name)
EOF"}

