{"command": "cat > src/util.rs <<'RSEOF'
//! Small utilities: RFC3339 timestamps, UUID v4 generation, HMAC-SHA256 and
//! anyhow-style error rendering used by the logger and the CLI.

use sha2::{Digest, Sha256};
use std::sync::Mutex;

/// Reads fresh entropy from the OS.  We keep a single handle around so that the
/// common case is a single `read` syscall.
struct Entropy {
    file: Mutex<Option<std::fs::File>>,
}

static ENTROPY: Entropy = Entropy {
    file: Mutex::new(None),
};

impl Entropy {
    fn fill(&self, buf: &mut [u8]) {
        let mut guard = self.file.lock().unwrap();
        loop {
            match guard.as_mut() {
                Some(f) => {
                    use std::io::Read;
                    match f.read_exact(buf) {
                        Ok(()) => return,
                        Err(_) => {
                            *guard = None;
                        }
                    }
                }
                None => {
                    use std::io::Read;
                    match std::fs::File::open("/dev/urandom") {
                        Ok(mut f) => {
                            if f.read_exact(buf).is_ok() {
                                *guard = Some(f);
                                return;
                            }
                        }
                        Err(_) => {}
                    }
                    // Fall back to a time based seed if /dev/urandom is not
                    // available at all.
                    let nanos = std::time::SystemTime::now()
                        .duration_since(std::time::UNIX_EPOCH)
                        .map(|d| d.as_nanos())
                        .unwrap_or(0) as u64;
                    let mut state = nanos ^ (nanos << 13);
                    for chunk in buf.chunks_mut(8) {
                        state = state
                            .wrapping_mul(6364136223846793005)
                            .wrapping_add(1442695040888963407);
                        let bytes = state.to_le_bytes();
                        for (i, slot) in chunk.iter_mut().enumerate() {
                            *slot = bytes[i];
                        }
                    }
                    return;
                }
            }
        }
    }
}

pub fn random_bytes(buf: &mut [u8]) {
    ENTROPY.fill(buf);
}

pub fn random_u32() -> u32 {
    let mut b = [0u8; 4];
    random_bytes(&mut b);
    u32::from_le_bytes(b)
}

/// Generates a random RFC 4122 version 4 UUID string.
pub fn uuid_v4() -> String {
    let mut b = [0u8; 16];
    random_bytes(&mut b);
    b[6] = (b[6] & 0x0f) | 0x40;
    b[8] = (b[8] & 0x3f) | 0x80;
    format_uuid(&b)
}

pub fn format_uuid(b: &[u8; 16]) -> String {
    const HEX: &[u8; 16] = b"0123456789abcdef";
    let mut out = String::with_capacity(36);
    let mut push = |n: u8, out: &mut String| {
        out.push(HEX[(n >> 4) as usize] as char);
        out.push(HEX[(n & 0x0f) as usize] as char);
    };
    for i in 0..4 {
        push(b[i], &mut out);
    }
    out.push('-');
    for i in 4..6 {
        push(b[i], &mut out);
    }
    out.push('-');
    for i in 6..8 {
        push(b[i], &mut out);
    }
    out.push('-');
    for i in 8..10 {
        push(b[i], &mut out);
    }
    out.push('-');
    for i in 10..16 {
        push(b[i], &mut out);
    }
    out
}

/// Parses a UUID string into its 16 raw bytes.
pub fn parse_uuid(s: &str) -> Option<[u8; 16]> {
    let mut out = [0u8; 16];
    let mut idx = 0usize;
    let mut hi: Option<u8> = None;
    for c in s.chars() {
        if c == '-' {
            continue;
        }
        let v = c.to_digit(16)? as u8;
        match hi {
            None => hi = Some(v),
            Some(h) => {
                if idx >= 16 {
                    return None;
                }
                out[idx] = (h << 4) | v;
                idx += 1;
                hi = None;
            }
        }
    }
    if idx == 16 && hi.is_none() {
        Some(out)
    } else {
        None
    }
}

pub fn hmac_sha256(key: &[u8], msg: &[u8]) -> [u8; 32] {
    let mut block = [0u8; 64];
    if key.len() > 64 {
        let mut h = Sha256::new();
        h.update(key);
        let d = h.finalize();
        block[..32].copy_from_slice(&d);
    } else {
        block[..key.len()].copy_from_slice(key);
    }
    let mut ipad = [0x36u8; 64];
    let mut opad = [0x5cu8; 64];
    for i in 0..64 {
        ipad[i] ^= block[i];
        opad[i] ^= block[i];
    }
    let mut inner = Sha256::new();
    inner.update(&ipad);
    inner.update(msg);
    let inner_hash = inner.finalize();
    let mut outer = Sha256::new();
    outer.update(&opad);
    outer.update(&inner_hash);
    let out = outer.finalize();
    let mut res = [0u8; 32];
    res.copy_from_slice(&out);
    res
}

/// Converts a unix timestamp (seconds + nanos) into an RFC 3339 string with
/// microsecond precision, matching what tracing's default formatter prints.
pub fn format_rfc3339(secs: u64, nanos: u32) -> String {
    let days = (secs / 86400) as i64;
    let rem = secs % 86400;
    let (y, m, d) = civil_from_days(days);
    let hour = (rem / 3600) as u32;
    let minute = ((rem % 3600) / 60) as u32;
    let second = (rem % 60) as u32;
    let micro = nanos / 1000;
    format!(
        "{:04}-{:02}-{:02}T{:02}:{:02}:{:02}.{:06}Z",
        y, m, d, hour, minute, second, micro
    )
}

fn civil_from_days(z: i64) -> (i64, u32, u32) {
    let z = z + 719468;
    let era = if z >= 0 { z } else { z - 146096 } / 146097;
    let doe = (z - era * 146097) as u64;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe as i64 + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32;
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32;
    (if m <= 2 { y + 1 } else { y }, m, d)
}

pub fn now() -> (u64, u32) {
    match std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH) {
        Ok(d) => (d.as_secs(), d.subsec_nanos()),
        Err(_) => (0, 0),
    }
}

/// Renders an error the same way `anyhow`'s `Debug` impl does (used because we
/// print it manually with the `Error: ` prefix, like `main() -> Result<()>`).
pub fn render_error(err: &anyhow::Error) -> String {
    let mut out = format!("Error: {}", err);
    let mut chain: Vec<String> = Vec::new();
    let mut cause = std::error::Error::source(err);
    while let Some(c) = cause {
        chain.push(c.to_string());
        cause = c.source();
    }
    if chain.is_empty() {
        return out;
    }
    out.push_str("\n\nCaused by:\n");
    if chain.len() == 1 {
        out.push_str("    ");
        out.push_str(&chain[0]);
    } else {
        for (i, c) in chain.iter().enumerate() {
            if i > 0 {
                out.push('\n');
            }
            out.push_str(&format!("    {}: {}", i, c));
        }
    }
    out.push('\n');
    out
}
RSEOF
echo ok; wc -l src/util.rs"}

