{"command": "cat > src/log.rs <<'RSEOF'
//! A tiny re-implementation of the subset of `tracing` + `tracing_subscriber`
//! behaviour that this program relies on: coloured single line events written to
//! stdout, a thread local span stack and an `EnvFilter` compatible `RUST_LOG`
//! parser.

use std::cell::RefCell;
use std::io::Write;
use std::sync::OnceLock;

pub const OFF: u8 = 0;
pub const ERROR: u8 = 1;
pub const WARN: u8 = 2;
pub const INFO: u8 = 3;
pub const DEBUG: u8 = 4;
pub const TRACE: u8 = 5;

const TARGET_CLIENT: &str = "bore_cli::client";
const TARGET_SERVER: &str = "bore_cli::server";
const TARGET_SHARED: &str = "bore_cli::shared";
const TARGET_CODEC: &str = "tokio_util::codec::framed_impl";

#[derive(Clone)]
struct Directive {
    target: Option<String>,
    level: u8,
}

struct Logger {
    directives: Vec<Directive>,
}

static LOGGER: OnceLock<Logger> = OnceLock::new();

fn parse_level(s: &str) -> Option<u8> {
    let lower = s.to_ascii_lowercase();
    match lower.as_str() {
        "off" => Some(OFF),
        "error" => Some(ERROR),
        "warn" => Some(WARN),
        "info" => Some(INFO),
        "debug" => Some(DEBUG),
        "trace" => Some(TRACE),
        "0" => Some(OFF),
        "1" => Some(ERROR),
        "2" => Some(WARN),
        "3" => Some(INFO),
        "4" => Some(DEBUG),
        "5" => Some(TRACE),
        _ => None,
    }
}

const LEVEL_ERR: &str =
    "error parsing level filter: expected one of \"off\", \"error\", \"warn\", \"info\", \"debug\", \"trace\", or a number 0-5";

/// Mirrors `EnvFilter::try_from_default_env` closely enough for our purposes:
/// directives are comma separated, `target=level`, a bare level applies
/// globally and a bare target defaults to TRACE.  A directive that cannot be
/// parsed aborts the parsing of the rest of the string (a warning is printed to
/// stderr first).
fn parse_env(raw: &str) -> Vec<Directive> {
    let mut out = Vec::new();
    for part in raw.split(',') {
        if part.is_empty() {
            continue;
        }
        if let Some(level) = parse_level(part) {
            out.push(Directive {
                target: None,
                level,
            });
            continue;
        }
        match part.split_once('=') {
            None => out.push(Directive {
                target: Some(part.to_string()),
                level: TRACE,
            }),
            Some((target, level_str)) => {
                if level_str.is_empty() {
                    continue;
                }
                match parse_level(level_str) {
                    Some(level) => out.push(Directive {
                        target: Some(target.to_string()),
                        level,
                    }),
                    None => {
                        eprintln!(
                            "Ignoring `RUST_LOG=\"{}\"`: {}",
                            raw,
                            LEVEL_ERR
                        );
                        return out;
                    }
                }
            }
        }
    }
    out
}

pub fn init() {
    let directives = match std::env::var("RUST_LOG") {
        Ok(raw) => parse_env(&raw),
        Err(_) => vec![Directive {
            target: None,
            level: INFO,
        }],
    };
    let _ = LOGGER.set(Logger { directives });
}

fn enabled(target: &str, level: u8) -> bool {
    match LOGGER.get() {
        None => level <= INFO,
        Some(l) => {
            let mut best: Option<u8> = None;
            for d in l.directives.iter() {
                let matches = match &d.target {
                    None => true,
                    Some(t) => target.starts_with(t.as_str()),
                };
                if matches {
                    best = Some(d.level);
                }
            }
            match best {
                None => false,
                Some(max) => level <= max,
            }
        }
    }
}

#[derive(Clone)]
struct Field {
    key: &'static str,
    value: String,
}

#[derive(Clone)]
struct SpanData {
    name: &'static str,
    fields: Vec<Field>,
}

thread_local! {
    static SPANS: RefCell<Vec<SpanData>> = RefCell::new(Vec::new());
}

/// Enters a span for the remainder of the current thread scope.
pub struct SpanGuard {
    _private: (),
}

impl Drop for SpanGuard {
    fn drop(&mut self) {
        SPANS.with(|s| {
            s.borrow_mut().pop();
        });
    }
}

pub fn enter_span(name: &'static str, fields: Vec<(&'static str, String)>) -> SpanGuard {
    SPANS.with(|s| {
        s.borrow_mut().push(SpanData {
            name,
            fields: fields
                .into_iter()
                .map(|(k, v)| Field {
                    key: k,
                    value: v,
                })
                .collect(),
        });
    });
    SpanGuard { _private: () }
}

fn write_span_chain(out: &mut String) {
    SPANS.with(|s| {
        for span in s.borrow().iter() {
            out.push_str("\x1b[1m");
            out.push_str(span.name);
            out.push_str("\x1b[0m\x1b[1m{\x1b[0m");
            for (i, f) in span.fields.iter().enumerate() {
                if i > 0 {
                    out.push(' ');
                }
                out.push_str("\x1b[3m");
                out.push_str(f.key);
                out.push_str("\x1b[0m\x1b[2m=\x1b[0m");
                out.push_str(&f.value);
            }
            out.push_str("\x1b[1m}\x1b[0m\x1b[2m:\x1b[0m ");
        }
    });
}

fn write_event(level: u8, target: &str, message: &str, fields: &[(&'static str, String)]) {
    if !enabled(target, level) {
        return;
    }
    let (secs, nanos) = crate::util::now();
    let mut out = String::with_capacity(160);
    out.push_str("\x1b[2m");
    out.push_str(&crate::util::format_rfc3339(secs, nanos));
    out.push_str("\x1b[0m ");
    let (text, color) = match level {
        ERROR => ("ERROR", "31"),
        WARN => (" WARN", "33"),
        INFO => (" INFO", "32"),
        DEBUG => ("DEBUG", "34"),
        _ => ("TRACE", "35"),
    };
    out.push_str("\x1b[");
    out.push_str(color);
    out.push('m');
    out.push_str(text);
    out.push_str("\x1b[0m ");
    write_span_chain(&mut out);
    out.push_str("\x1b[2m");
    out.push_str(target);
    out.push_str("\x1b[0m\x1b[2m:\x1b[0m ");
    out.push_str(message);
    for (k, v) in fields {
        out.push_str(" \x1b[3m");
        out.push_str(k);
        out.push_str("\x1b[0m\x1b[2m=\x1b[0m");
        out.push_str(v);
    }
    out.push('\n');
    let stdout = std::io::stdout();
    let mut lock = stdout.lock();
    let _ = lock.write_all(out.as_bytes());
    let _ = lock.flush();
}

pub fn error(target: &str, message: &str, fields: &[(&'static str, String)]) {
    write_event(ERROR, target, message, fields);
}
pub fn warn(target: &str, message: &str, fields: &[(&'static str, String)]) {
    write_event(WARN, target, message, fields);
}
pub fn info(target: &str, message: &str, fields: &[(&'static str, String)]) {
    write_event(INFO, target, message, fields);
}
pub fn debug(target: &str, message: &str, fields: &[(&'static str, String)]) {
    write_event(DEBUG, target, message, fields);
}
pub fn trace(target: &str, message: &str, fields: &[(&'static str, String)]) {
    write_event(TRACE, target, message, fields);
}

pub fn client_info(message: &str, fields: &[(&'static str, String)]) {
    info(TARGET_CLIENT, message, fields);
}
pub fn client_warn(message: &str, fields: &[(&'static str, String)]) {
    warn(TARGET_CLIENT, message, fields);
}
pub fn client_error(message: &str, fields: &[(&'static str, String)]) {
    error(TARGET_CLIENT, message, fields);
}
pub fn server_info(message: &str, fields: &[(&'static str, String)]) {
    info(TARGET_SERVER, message, fields);
}
pub fn server_warn(message: &str, fields: &[(&'static str, String)]) {
    warn(TARGET_SERVER, message, fields);
}

// ---- shared codec level tracing helpers -----------------------------------

pub fn trace_wait_msg() {
    trace(TARGET_SHARED, "waiting to receive json message", &[]);
}
pub fn trace_send_msg() {
    trace(TARGET_SHARED, "sending json message", &[]);
}
pub fn trace_codec_decode_attempt() {
    trace(TARGET_CODEC, "attempting to decode a frame", &[]);
}
pub fn trace_codec_decoded() {
    trace(TARGET_CODEC, "frame decoded from buffer", &[]);
}
pub fn trace_codec_flushing() {
    trace(TARGET_CODEC, "flushing framed transport", &[]);
}
pub fn trace_codec_writing(len: usize) {
    trace(
        TARGET_CODEC,
        "writing; remaining",
        &[("remaining", len.to_string())],
    );
}
pub fn trace_codec_flushed() {
    trace(TARGET_CODEC, "framed transport flushed", &[]);
}
RSEOF
echo ok"}

