//! Wire protocol: JSON messages delimited by a NUL byte, challenge/response
//! authentication based on HMAC-SHA256 and a small framed reader/writer on top
//! of a blocking TCP stream.

use crate::log;
use anyhow::{anyhow, Context, Result};
use serde::{Deserialize, Serialize};
use sha2::Digest;
use std::io::{Read, Write};
use std::net::{Shutdown, TcpStream};
use std::time::{Duration, Instant};

/// TCP port used for the control channel of the server and by the clients.
pub const CONTROL_PORT: u16 = 7835;

/// Timeout applied while waiting for the first message on a connection.
pub const INITIAL_TIMEOUT: Duration = Duration::from_secs(3);

/// How often the server pings its clients.
pub const HEARTBEAT_INTERVAL: Duration = Duration::from_millis(500);

/// How many random ports the server tries before giving up.
pub const PORT_ATTEMPTS: usize = 100;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Uuid(pub [u8; 16]);

impl Uuid {
    pub fn new() -> Uuid {
        let mut b = [0u8; 16];
        crate::util::random_bytes(&mut b);
        b[6] = (b[6] & 0x0f) | 0x40;
        b[8] = (b[8] & 0x3f) | 0x80;
        Uuid(b)
    }
}

impl std::fmt::Display for Uuid {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&crate::util::format_uuid(&self.0))
    }
}

impl Serialize for Uuid {
    fn serialize<S: serde::Serializer>(&self, s: S) -> Result<S::Ok, S::Error> {
        s.serialize_str(&crate::util::format_uuid(&self.0))
