                if e.kind() == std::io::ErrorKind::Interrupted {
                    return Ok(0);
                }
                Err(e)
            }
        }
    }

    fn take_frame(&mut self) -> Option<Vec<u8>> {
        if let Some(pos) = self.buf.iter().position(|b| *b == 0) {
            let frame: Vec<u8> = self.buf.drain(..pos).collect();
            self.buf.remove(0);
            Some(frame)
        } else {
            None
        }
    }

    fn next_frame(&mut self, timeout: Option<Duration>) -> Result<Option<Vec<u8>>> {
        let deadline = timeout.map(|t| Instant::now() + t);
        log::trace_wait_msg();
        loop {
            log::trace_codec_decode_attempt();
            if let Some(frame) = self.take_frame() {
                log::trace_codec_decoded();
                return Ok(Some(frame));
            }
            let mut wait_ms: i64 = 100;
            if let Some(d) = deadline {
                let now = Instant::now();
                if now >= d {
                    return Err(anyhow!("deadline has elapsed"));
                }
                wait_ms = ((d - now).as_millis() as i64).max(1);
            }
            match poll_readable(self.sock.as_raw_fd(), wait_ms) {
                Ok(true) => {
                    let n = self.read_more()?;
                    if n == 0 {
                        // EOF: an incomplete trailing frame is still handed
                        // back to the caller so that it can be parsed.
                        if self.buf.is_empty() {
                            return Ok(None);
                        }
                        let frame = std::mem::take(&mut self.buf);
                        return Ok(Some(frame));
                    }
                }
                Ok(false) => {}
                Err(e) => {
                    return Err(anyhow!(e).context("frame error, invalid byte length"));
                }
            }
        }
    }

    pub fn recv_server_timeout(&mut self, timeout: Duration) -> Result<Option<ServerMessage>> {
        match self.next_frame(Some(timeout))? {
            None => Ok(None),
            Some(frame) => parse_server(&frame),
        }
    }

    pub fn recv_server(&mut self) -> Result<Option<ServerMessage>> {
        match self.next_frame(None)? {
            None => Ok(None),
            Some(frame) => parse_server(&frame),
        }
    }

    pub fn recv_client_timeout(&mut self, timeout: Duration) -> Result<Option<ClientMessage>> {
        match self.next_frame(Some(timeout))? {
            None => Ok(None),
            Some(frame) => parse_client(&frame),
        }
    }

    pub fn recv_client(&mut self) -> Result<Option<ClientMessage>> {
        match self.next_frame(None)? {
            None => Ok(None),
            Some(frame) => parse_client(&frame),
        }
    }

    /// Blocking read of the raw byte stream (used for relaying data).
    pub fn read_raw(&mut self, buf: &mut [u8]) -> std::io::Result<usize> {
        self.sock.read(buf)
    }
}

impl WriteHalf {
    pub fn send(&mut self, msg: &ServerMessage) -> Result<()> {
        let data = serde_json::to_vec(msg).context("unable to parse message")?;
        self.write_frame(&data)
    }

    pub fn send_client(&mut self, msg: &ClientMessage) -> Result<()> {
        let data = serde_json::to_vec(msg).context("unable to parse message")?;
        self.write_frame(&data)
    }

    fn write_frame(&mut self, data: &[u8]) -> Result<()> {
        log::trace_send_msg();
        log::trace_codec_flushing();
        let mut out = Vec::with_capacity(data.len() + 1);
        out.extend_from_slice(data);
        out.push(0u8);
        log::trace_codec_writing(out.len());
        self.sock.write_all(&out).map_err(|e| anyhow!(e))?;
        log::trace_codec_flushed();
        Ok(())
    }

    pub fn write_raw(&mut self, buf: &[u8]) -> std::io::Result<usize> {
        self.sock.write(buf)
    }

    pub fn shutdown_write(&self) -> std::io::Result<()> {
        self.sock.shutdown(Shutdown::Write)
    }
}

pub fn parse_server(frame: &[u8]) -> Result<Option<ServerMessage>> {
    serde_json::from_slice::<ServerMessage>(frame)
        .map(Some)
        .map_err(|e| anyhow!(e).context("unable to parse message"))
}

pub fn parse_client(frame: &[u8]) -> Result<Option<ClientMessage>> {
    serde_json::from_slice::<ClientMessage>(frame)
        .map(Some)
        .map_err(|e| anyhow!(e).context("unable to parse message"))
}
