//! The remote side of the tunnel: accepts control connections, hands out
//! tunnel ports and relays data between remote peers and the client.

use crate::log;
use crate::proto::*;
use anyhow::{anyhow, Context, Result};
use std::collections::VecDeque;
use std::net::{IpAddr, SocketAddr, TcpListener, TcpStream};
use std::sync::atomic::{AtomicBool, AtomicU64, Ordering};
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

pub struct ServerConfig {
    pub min_port: u16,
    pub max_port: u16,
    pub secret: Option<String>,
    pub bind_addr: IpAddr,
    pub bind_tunnels: IpAddr,
}

struct Entry {
    port: u16,
    control_peer: String,
    writer: WriteHalf,
    pending: Mutex<VecDeque<(Uuid, TcpStream)>>,
    listener: TcpListener,
    alive: AtomicBool,
    dead_tick: Mutex<Option<u64>>,
}

struct Registry {
    map: Mutex<std::collections::HashMap<u16, Arc<Entry>>>,
}

impl Registry {
    fn new() -> Registry {
        Registry {
            map: Mutex::new(std::collections::HashMap::new()),
        }
    }

    fn insert(&self, port: u16, entry: Arc<Entry>) {
        self.map.lock().unwrap().insert(port, entry);
    }

    fn release(&self, port: u16) {
        if let Some(entry) = self.map.lock().unwrap().remove(&port) {
            entry.alive.store(false, Ordering::SeqCst);
        }
    }

    fn take_pending(&self, id: &Uuid) -> Option<TcpStream> {
        for (_port, entry) in self.map.lock().unwrap().iter() {
            let mut q = entry.pending.lock().unwrap();
            if let Some(idx) = q.iter().position(|(i, _)| i == id) {
                let (_, sock) = q.remove(idx).unwrap();
                return Some(sock);
            }
        }
        None
    }
}

static TICK_COUNT: AtomicU64 = AtomicU64::new(0);
static TICK_BASE: Mutex<Option<Instant>> = Mutex::new(None);

fn ticker_start() -> Instant {
    let mut guard = TICK_BASE.lock().unwrap();
    match *guard {
        Some(t) => t,
        None => {
            let t = Instant::now();
            *guard = Some(t);
            t
        }
    }
}

fn next_tick(base: Instant) -> Instant {
    let elapsed = base.elapsed();
    let step = HEARTBEAT_INTERVAL.as_millis() as u64;
    let k = elapsed.as_millis() as u64 / step + 1;
    base + Duration::from_millis(k * step)
}

fn top_message(err: &anyhow::Error) -> String {
    err.to_string()
}

pub fn run(cfg: ServerConfig) -> Result<()> {
    let listener =
        TcpListener::bind((cfg.bind_addr, CONTROL_PORT)).with_context(|| {
            format!("could not listen on {}:{}", cfg.bind_addr, CONTROL_PORT)
        })?;
    log::server_info(
        "server listening",
        &[("addr", cfg.bind_addr.to_string())],
    );

    let reg = Arc::new(Registry::new());
    let cfg = Arc::new(cfg);

    // Periodic ticker: drives heartbeats and the delayed release of tunnel
    // ports belonging to clients that went away.
    {
        let reg = Arc::clone(&reg);
        std::thread::spawn(move || {
            let base = ticker_start();
            loop {
                let until = next_tick(base);
                let now = Instant::now();
                if until > now {
                    std::thread::sleep(until - now);
                }
                let tick = TICK_COUNT.fetch_add(1, Ordering::SeqCst) + 1;
                // Release tunnels whose client disappeared at an earlier tick.
                let dead: Vec<u16> = {
                    let map = reg.map.lock().unwrap();
                    map.iter()
                        .filter_map(|(port, entry)| {
                            let d = entry.dead_tick.lock().unwrap();
                            match *d {
                                Some(t) if t < tick => Some(*port),
                                _ => None,
                            }
                        })
                        .collect()
                };
                for port in dead {
                    reg.release(port);
                }
            }
        });
    }

    for conn in listener.incoming() {
        match conn {
            Ok(sock) => {
                let peer = match sock.peer_addr() {
                    Ok(p) => p,
                    Err(_) => continue,
                };
                let reg = Arc::clone(&reg);
                let cfg = Arc::clone(&cfg);
                std::thread::spawn(move || {
                    handle_connection(sock, peer, reg, cfg);
                });
            }
            Err(_) => continue,
        }
    }
    Ok(())
}

fn handle_connection(
    sock: TcpStream,
    peer: SocketAddr,
    reg: Arc<Registry>,
    cfg: Arc<ServerConfig>,
) {
    let _span = log::enter_span("control", vec![("addr", peer.to_string())]);
    log::server_info("incoming connection", &[]);
    let mut chan = match Chan::new(sock) {
        Ok(c) => c,
        Err(_) => {
            log::server_info("connection exited", &[]);
            return;
        }
    };

    // ---- authentication ---------------------------------------------------
    if let Some(secret) = &cfg.secret {
        let challenge = Uuid::new();
        if chan.send(&ServerMessage::Challenge(challenge)).is_err() {
            log::server_info("connection exited", &[]);
            return;
        }
        match chan.recv_client_timeout(INITIAL_TIMEOUT) {
            Ok(Some(ClientMessage::Authenticate(hash))) => {
                if hash != auth_hash(secret, &challenge) {
                    let _ = chan.send(&ServerMessage::Error("invalid secret".to_string()));
                    log::server_warn(
                        "server handshake failed",
                        &[("err", "invalid secret".to_string())],
                    );
                    log::server_info("connection exited", &[]);
                    return;
                }
            }
            Ok(Some(_)) => {
                let msg = "server requires secret, but no secret was provided";
                let _ = chan.send(&ServerMessage::Error(msg.to_string()));
                log::server_warn("server handshake failed", &[("err", msg.to_string())]);
                log::server_info("connection exited", &[]);
                return;
            }
            Ok(None) => {
                log::server_info("connection exited", &[]);
                return;
            }
            Err(e) => {
                log::server_warn(
                    "connection exited with error",
                    &[("err", top_message(&e))],
                );
                return;
            }
        }
    }

    // ---- dispatch on the first message ------------------------------------
    let msg = match chan.recv_client_timeout(INITIAL_TIMEOUT) {
        Ok(Some(m)) => m,
        Ok(None) => {
            log::server_info("connection exited", &[]);
            return;
        }
        Err(e) => {
            log::server_warn("connection exited with error", &[("err", top_message(&e))]);
            return;
        }
    };

    match msg {
        ClientMessage::Hello(port) => {
            handle_client(chan, peer, port, reg, cfg);
        }
        ClientMessage::Accept(id) => {
            handle_forward(chan, id, reg);
        }
        ClientMessage::Authenticate(_) => {
            log::server_warn("unexpected authenticate", &[]);
            log::server_info("connection exited", &[]);
        }
    }
}

fn handle_client(
    mut chan: Chan,
    peer: SocketAddr,
    port: u16,
    reg: Arc<Registry>,
    cfg: Arc<ServerConfig>,
) {
    let (listener, assigned) = match select_port(&cfg, port) {
        Ok(v) => v,
        Err(e) => {
            let _ = chan.send(&ServerMessage::Error(top_message(&e)));
            log::server_info("connection exited", &[]);
            return;
        }
    };
    if chan.send(&ServerMessage::Hello(assigned)).is_err() {
        return;
    }
    log::server_info(
        "new client",
        &[
            ("host", cfg.bind_tunnels.to_string()),
            ("port", assigned.to_string()),
        ],
    );

    let entry = Arc::new(Entry {
        port: assigned,
        control_peer: peer.to_string(),
        writer: chan.writer,
        pending: Mutex::new(VecDeque::new()),
        listener: listener.try_clone().unwrap(),
        alive: AtomicBool::new(true),
        dead_tick: Mutex::new(None),
    });
    reg.insert(assigned, Arc::clone(&entry));

    {
        let entry = Arc::clone(&entry);
        std::thread::spawn(move || accept_loop(entry));
    }

    // Heartbeat loop.  The client is considered gone as soon as a write fails.
    let base = ticker_start();
    loop {
        let until = next_tick(base);
        let now = Instant::now();
        if until > now {
            std::thread::sleep(until - now);
        }
        if !entry.alive.load(Ordering::SeqCst) {
            break;
        }
        if chan.send(&ServerMessage::Heartbeat).is_err() {
            break;
        }
    }
    let tick = TICK_COUNT.load(Ordering::SeqCst);
    *entry.dead_tick.lock().unwrap() = Some(tick);
    log::server_info("connection exited", &[]);
}

fn accept_loop(entry: Arc<Entry>) {
    let listener = match entry.listener.try_clone() {
        Ok(l) => l,
        Err(_) => return,
    };
    let _span = log::enter_span(
        "control",
        vec![("addr", entry.control_peer.clone())],
    );
    loop {
        if !entry.alive.load(Ordering::SeqCst) {
            return;
        }
        match wait_readable(listener.as_raw_fd(), 100) {
            Ok(false) => continue,
            Err(_) => return,
            Ok(true) => {}
        }
        let (sock, peer) = match listener.accept() {
            Ok(v) => v,
            Err(e) => {
                if e.kind() == std::io::ErrorKind::WouldBlock {
                    continue;
                }
                return;
            }
        };
        if !entry.alive.load(Ordering::SeqCst) {
            return;
        }
        let id = Uuid::new();
        log::server_info(
            "new connection",
            &[
                ("addr", peer.to_string()),
                ("port", entry.port.to_string()),
            ],
        );
        {
            let mut writer = entry.writer.sock(); // hmm
        }
        let mut writer = WriteHalf {
            sock: match entry.writer_sock() {
                Ok(s) => s,
                Err(_) => return,
            },
        };
        if writer.send(&ServerMessage::Connection(id)).is_err() {
            return;
        }
        entry
            .pending
            .lock()
            .unwrap()
            .push_back((id, sock));
    }
}

fn wait_readable(fd: i32, timeout_ms: i64) -> std::io::Result<bool> {
    let mut pfd = libc::pollfd {
        fd,
        events: libc::POLLIN,
        revents: 0,
    };
    let r = unsafe { libc::poll(&mut pfd as *mut libc::pollfd, 1, timeout_ms as libc::c_int) };
    if r < 0 {
        Err(std::io::Error::last_os_error())
    } else {
        Ok(r > 0)
    }
}

fn handle_forward(mut chan: Chan, id: Uuid, reg: Arc<Registry>) {
    log::server_info("forwarding connection", &[("id", id.to_string())]);
    let remote = match reg.take_pending(&id) {
        Some(s) => s,
        None => {
            log::server_warn("missing connection", &[("id", id.to_string())]);
            log::server_info("connection exited", &[]);
            return;
        }
    };
    let (reader, writer) = chan.split();
    let errs: Arc<Mutex<Option<String>>> = Arc::new(Mutex::new(None));
    let mut remote_rd = remote.try_clone().ok();
    let remote_wr = remote;
    let errs2 = Arc::clone(&errs);

    let t1 = std::thread::spawn(move || {
        let mut w = remote_wr;
        crate::relay::copy_from_reader(reader, &mut w, &errs2);
    });
    let t2 = std::thread::spawn(move || {
        let mut r = remote_rd.take().unwrap();
        crate::relay::copy_to_writer(&mut r, writer, &errs);
    });
    let _ = t1.join();
    let _ = t2.join();
    let recorded = errs.lock().unwrap().take();
    match recorded {
        Some(e) => log::server_warn("connection exited with error", &[("err", e)]),
        None => log::server_info("connection exited", &[]),
    }
}

fn select_port(cfg: &ServerConfig, requested: u16) -> Result<(TcpListener, u16)> {
    if requested != 0 {
        if requested < cfg.min_port || requested > cfg.max_port {
            return Err(anyhow!("client port number not in allowed range"));
        }
        return match TcpListener::bind((cfg.bind_tunnels, requested)) {
            Ok(l) => Ok((l, requested)),
            Err(e) => {
                if e.kind() == std::io::ErrorKind::AddrInUse {
                    Err(anyhow!("port already in use"))
                } else {
                    Err(anyhow!(e))
                }
            }
        };
    }
    let range = cfg.max_port as u32 - cfg.min_port as u32 + 1;
    for _ in 0..PORT_ATTEMPTS {
        let off = crate::util::random_u32() % range;
        let port = cfg.min_port + off as u16;
        if let Ok(l) = TcpListener::bind((cfg.bind_tunnels, port)) {
            return Ok((l, port));
        }
    }
    Err(anyhow!("failed to find an available port"))
}
