//! The remote side of the tunnel: accepts control connections, hands out
//! tunnel ports and relays data between remote peers and the client.

use crate::log;
use crate::proto::*;
use anyhow::{anyhow, Context, Result};
use std::collections::VecDeque;
use std::net::{IpAddr, SocketAddr, TcpListener, TcpStream};
use std::sync::atomic::{AtomicBool, AtomicU64, Ordering};
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

pub struct ServerConfig {
    pub min_port: u16,
    pub max_port: u16,
    pub secret: Option<String>,
    pub bind_addr: IpAddr,
    pub bind_tunnels: IpAddr,
}

struct Entry {
    port: u16,
    control_peer: String,
    writer: WriteHalf,
    pending: Mutex<VecDeque<(Uuid, TcpStream)>>,
    listener: TcpListener,
    alive: AtomicBool,
    dead_tick: Mutex<Option<u64>>,
}

struct Registry {
    map: Mutex<std::collections::HashMap<u16, Arc<Entry>>>,
}

impl Registry {
    fn new() -> Registry {
        Registry {
            map: Mutex::new(std::collections::HashMap::new()),
        }
    }

    fn insert(&self, port: u16, entry: Arc<Entry>) {
        self.map.lock().unwrap().insert(port, entry);
    }

    fn release(&self, port: u16) {
        if let Some(entry) = self.map.lock().unwrap().remove(&port) {
            entry.alive.store(false, Ordering::SeqCst);
        }
    }

    fn take_pending(&self, id: &Uuid) -> Option<TcpStream> {
        for (_port, entry) in self.map.lock().unwrap().iter() {
            let mut q = entry.pending.lock().unwrap();
            if let Some(idx) = q.iter().position(|(i, _)| i == id) {
                let (_, sock) = q.remove(idx).unwrap();
                return Some(sock);
            }
        }
        None
    }
}

static TICK_COUNT: AtomicU64 = AtomicU64::new(0);
static TICK_BASE: Mutex<Option<Instant>> = Mutex::new(None);

fn ticker_start() -> Instant {
    let mut guard = TICK_BASE.lock().unwrap();
    match *guard {
        Some(t) => t,
        None => {
            let t = Instant::now();
            *guard = Some(t);
            t
        }
    }
}

fn next_tick(base: Instant) -> Instant {
    let elapsed = base.elapsed();
    let step = HEARTBEAT_INTERVAL.as_millis() as u64;
    let k = elapsed.as_millis() as u64 / step + 1;
    base + Duration::from_millis(k * step)
}

fn top_message(err: &anyhow::Error) -> String {
    err.to_string()
}

pub fn run(cfg: ServerConfig) -> Result<()> {
    let listener =
        TcpListener::bind((cfg.bind_addr, CONTROL_PORT)).with_context(|| {
            format!("could not listen on {}:{}", cfg.bind_addr, CONTROL_PORT)
        })?;
    log::server_info(
        "server listening",
        &[("addr", cfg.bind_addr.to_string())],
    );

    let reg = Arc::new(Registry::new());
    let cfg = Arc::new(cfg);

    // Periodic ticker: drives heartbeats and the delayed release of tunnel
    // ports belonging to clients that went away.
    {
        let reg = Arc::clone(&reg);
        std::thread::spawn(move || {
            let base = ticker_start();
            loop {
                let until = next_tick(base);
