//! Bidirectional copy between two streams, matching the observable behaviour of
//! the original tool: when one direction sees EOF the write side of the peer is
//! half closed and any error while doing so is reported.

use std::io::{Read, Write};
use std::sync::{Arc, Mutex};

pub type ErrSlot = Arc<Mutex<Option<String>>>;

pub fn record_error(slot: &ErrSlot, err: std::io::Error) {
    let mut guard = slot.lock().unwrap();
    if guard.is_none() {
        *guard = Some(err.to_string());
    }
}

pub fn record_message(slot: &ErrSlot, msg: String) {
    let mut guard = slot.lock().unwrap();
    if guard.is_none() {
        *guard = Some(msg);
    }
}

/// Copies everything read from `reader` into `writer`.
pub fn copy_read_into<R: Read, W: Write>(
    mut reader: R,
    writer: &mut W,
    errs: &ErrSlot,
) {
    let mut buf = [0u8; 8192];
    loop {
        match reader.read(&mut buf) {
            Ok(0) => {
                if let Err(e) = writer.shutdown_write() {
                    record_error(errs, e);
                }
                return;
            }
            Ok(n) => {
                let mut off = 0usize;
                while off < n {
                    match writer.write(&buf[off..n]) {
                        Ok(0) => {
                            record_error(errs, std::io::Error::new(
                                std::io::ErrorKind::WriteZero,
                                "failed to write whole buffer",
                            ));
                            return;
                        }
                        Ok(m) => off += m,
                        Err(e) => {
                            record_error(errs, e);
                            return;
                        }
                    }
                }
            }
            Err(e) => {
                if e.kind() == std::io::ErrorKind::Interrupted {
                    continue;
                }
                record_error(errs, e);
                return;
            }
        }
    }
}

/// Reads from a [`crate::proto::ReadHalf`] (which may buffer part of a frame)
/// and writes the bytes into `writer`.
pub fn copy_channel_into(
    reader: &mut crate::proto::ReadHalf,
    writer: &mut crate::proto::WriteHalf,
    errs: &ErrSlot,
) {
    let mut buf = [0u8; 8192];
    loop {
        let n = match reader.read_raw(&mut buf) {
            Ok(0) => {
                if let Err(e) = writer.shutdown_write() {
                    record_error(errs, e);
                }
                return;
            }
            Ok(n) => n,
            Err(e) => {
                if e.kind() == std::io::ErrorKind::Interrupted {
                    continue;
                }
                record_error(errs, e);
                return;
            }
