                Ok(0) => {
                    record_message(
                        errs,
                        "failed to write whole buffer".to_string(),
                    );
                    return;
                }
                Ok(m) => off += m,
                Err(e) => {
                    record_error(errs, e);
                    return;
                }
            }
        }
    }
}
