            return;
        }
        entry.pending.lock().unwrap().push_back((id, sock));
    }
}

fn wait_readable(fd: i32, timeout_ms: i64) -> std::io::Result<bool> {
    let mut pfd = libc::pollfd {
        fd,
        events: libc::POLLIN,
        revents: 0,
    };
    let r = unsafe { libc::poll(&mut pfd as *mut libc::pollfd, 1, timeout_ms as libc::c_int) };
    if r < 0 {
        Err(std::io::Error::last_os_error())
    } else {
        Ok(r > 0)
    }
}

fn handle_forward(mut chan: Chan, id: Uuid, reg: Arc<Registry>) {
    log::server_info("forwarding connection", &[("id", id.to_string())]);
    let remote = match reg.take_pending(&id) {
        Some(s) => s,
        None => {
            log::server_warn("missing connection", &[("id", id.to_string())]);
            log::server_info("connection exited", &[]);
            return;
        }
    };
    let (mut reader, mut writer) = chan.split();
    let errs: ErrSlot = Arc::new(Mutex::new(None));
    let errs2 = Arc::clone(&errs);
    let mut remote_rd = match remote.try_clone() {
        Ok(s) => s,
        Err(_) => return,
    };
    let mut remote_wr = remote;
    let t1 = std::thread::spawn(move || {
        copy_channel_into(&mut reader, &mut writer, &errs);
    });
    let t2 = std::thread::spawn(move || {
        copy_read_into(&mut remote_rd, &mut remote_wr, &errs2);
    });
    let _ = t1.join();
    let _ = t2.join();
    let recorded = errs.lock().unwrap().take();
    match recorded {
        Some(e) => log::server_warn("connection exited with error", &[("err", e)]),
        None => log::server_info("connection exited", &[]),
    }
}

fn select_port(cfg: &ServerConfig, requested: u16) -> Result<(TcpListener, u16)> {
    if requested != 0 {
        if requested < cfg.min_port || requested > cfg.max_port {
            return Err(anyhow!("client port number not in allowed range"));
        }
        return match TcpListener::bind((cfg.bind_tunnels, requested)) {
            Ok(l) => Ok((l, requested)),
            Err(e) => {
                if e.kind() == std::io::ErrorKind::AddrInUse {
                    Err(anyhow!("port already in use"))
                } else {
                    Err(anyhow!(e))
                }
            }
        };
    }
    let range = cfg.max_port as u32 - cfg.min_port as u32 + 1;
    for _ in 0..PORT_ATTEMPTS {
        let off = crate::util::random_u32() % range;
        let port = cfg.min_port + off as u16;
        if let Ok(l) = TcpListener::bind((cfg.bind_tunnels, port)) {
            return Ok((l, port));
        }
    }
    Err(anyhow!("failed to find an available port"))
}
