                        "server handshake failed",
                        &[("err", "invalid secret".to_string())],
                    );
                    log::server_info("connection exited", &[]);
                    return;
                }
            }
            Ok(Some(_)) => {
                let msg = "server requires secret, but no secret was provided";
                let _ = chan.send(&ServerMessage::Error(msg.to_string()));
                log::server_warn("server handshake failed", &[("err", msg.to_string())]);
                log::server_info("connection exited", &[]);
                return;
