{"command": "cat > src/client.rs <<'RSEOF'
//! The local side of the tunnel: connects to the server, registers a local
//! service under a remote port and relays connections that the server forwards.

use crate::log;
use crate::proto::*;
use crate::relay::{copy_channel_into, copy_read_into, record_error, ErrSlot};
use anyhow::{anyhow, bail, Result};
use std::net::{TcpStream, UdpSocket};
use std::sync::{Arc, Mutex};
use std::time::Duration;

pub struct ClientConfig {
    pub local_port: u16,
    pub local_host: String,
    pub to: String,
    pub port: u16,
    pub secret: Option<String>,
}

fn dial(cfg: &ClientConfig) -> Result<TcpStream> {
    TcpStream::connect((cfg.to.as_str(), CONTROL_PORT)).map_err(|e| {
        anyhow!(e).context(format!(
            "could not connect to {}:{}",
            cfg.to, CONTROL_PORT
        ))
    })
}

fn connect_local(cfg: &ClientConfig) -> Result<TcpStream> {
    TcpStream::connect((cfg.local_host.as_str(), cfg.local_port)).map_err(|e| {
        anyhow!(e).context(format!(
            "could not connect to {}:{}",
            cfg.local_host, cfg.local_port
        ))
    })
}

/// Performs the challenge/response handshake when a secret is configured.
fn authenticate(chan: &mut Chan, secret: &Option<String>) -> Result<()> {
    if let Some(secret) = secret {
        match chan.recv_timeout(INITIAL_TIMEOUT)? {
            Some(ServerMessage::Challenge(challenge)) => {
                chan.send_client(&ClientMessage::Authenticate(auth_hash(
                    secret,
                    &challenge,
                )))?;
            }
            Some(ServerMessage::Error(e)) => bail!("server error: {}", e),
            Some(_) => bail!("server requires authentication, but no client secret was provided"),
            None => bail!("unexpected EOF"),
        }
    }
    Ok(())
}

pub fn run(cfg: ClientConfig) -> Result<()> {
    let conn = dial(&cfg)?;
    let local_ip = local_ip_of(&conn);
    let mut chan = Chan::new(conn)?;

    authenticate(&mut chan, &cfg.secret)?;
    chan.send_client(&ClientMessage::Hello(cfg.port))?;

    let remote_port = match chan.recv_timeout(INITIAL_TIMEOUT)? {
        Some(ServerMessage::Hello(port)) => port,
        Some(ServerMessage::Challenge(_)) => {
            bail!("server requires authentication, but no client secret was provided")
        }
        Some(ServerMessage::Error(e)) => bail!("server error: {}", e),
        Some(_) => bail!("unexpected initial non-hello message"),
        None => bail!("unexpected EOF"),
    };

    log::client_info(
        "connected to server",
        &[("remote_port", remote_port.to_string())],
    );
    log::client_info(&format!("listening at {}:{}", local_ip, remote_port), &[]);

    let cfg = Arc::new(cfg);
    loop {
        match chan.recv()? {
            Some(ServerMessage::Connection(id)) => {
                let cfg = Arc::clone(&cfg);
                std::thread::spawn(move || {
                    let _span = log::enter_span("proxy", vec![("id", id.to_string())]);
                    log::client_info("new connection", &[]);
                    match run_proxy(&cfg, id) {
                        Ok(()) => log::client_info("connection exited", &[]),
                        Err(e) => log::client_warn(
                            "connection exited with error",
                            &[("err", e.to_string())],
                        ),
                    }
                });
            }
            Some(ServerMessage::Heartbeat) => continue,
            Some(ServerMessage::Error(e)) => {
                log::client_error("server error", &[("err", e)]);
            }
            Some(ServerMessage::Challenge(_)) => {
                log::client_warn("unexpected challenge", &[]);
            }
            Some(ServerMessage::Hello(_)) => {
                log::client_warn("unexpected hello", &[]);
            }
            None => return Ok(()),
        }
    }
}

fn run_proxy(cfg: &ClientConfig, id: Uuid) -> Result<()> {
    let conn = dial(cfg)?;
    let mut chan = Chan::new(conn)?;
    authenticate(&mut chan, &cfg.secret)?;
    chan.send_client(&ClientMessage::Accept(id))?;

    let mut local = connect_local(cfg)?;
    local.set_nodelay(true).ok();
    let mut local_wr = local.try_clone().map_err(|e| anyhow!(e))?;

    let (mut reader, mut writer) = chan.split();
    let errs: ErrSlot = Arc::new(Mutex::new(None));
    let errs2 = Arc::clone(&errs);
    let t1 = std::thread::spawn(move || {
        copy_channel_into(&mut reader, &mut local_wr, &errs);
    });
    let t2 = std::thread::spawn(move || {
        copy_read_into(&mut local, &mut writer, &errs2);
    });
    let _ = t1.join();
    let _ = t2.join();
    match errs.lock().unwrap().take() {
        Some(msg) => Err(anyhow!(msg)),
        None => Ok(()),
    }
}

/// Determines the local address that was used for the control connection, which
/// is what the original prints in its "listening at" message.
fn local_ip_of(conn: &TcpStream) -> String {
    match conn.local_addr() {
        Ok(a) => a.ip().to_string(),
        Err(_) => {
            // Fall back to discovering the source address that would be used to
            // reach the server.
            let s = UdpSocket::bind("0.0.0.0:0").ok();
            match s {
                Some(s) => match s.connect(("127.0.0.1", 1)) {
                    Ok(()) => s.local_addr().map(|a| a.ip().to_string()).unwrap_or_default(),
                    Err(_) => String::new(),
                },
                None => String::new(),
            }
        }
    }
}

/// Re-exported for the client's own use in tests.
pub fn timeout(d: Duration) -> Duration {
    d
}
RSEOF
