//! Bidirectional copy between two streams.  When one direction reaches EOF the
//! write side of the peer is half closed; failures to do so (as well as read
//! and write errors) are reported to the caller so that they can be logged.

use crate::proto::{ReadHalf, WriteHalf};
use std::net::{Shutdown, TcpStream};
use std::sync::{Arc, Mutex};

pub type ErrSlot = Arc<Mutex<Option<String>>>;

pub fn record_error(slot: &ErrSlot, err: std::io::Error) {
    let mut guard = slot.lock().unwrap();
    if guard.is_none() {
        *guard = Some(err.to_string());
    }
}

pub fn record_message(slot: &ErrSlot, msg: String) {
    let mut guard = slot.lock().unwrap();
    if guard.is_none() {
        *guard = Some(msg);
    }
}

pub trait InStream {
    fn read_raw(&mut self, buf: &mut [u8]) -> std::io::Result<usize>;
}

pub trait OutStream {
    fn write_all_raw(&mut self, buf: &[u8]) -> std::io::Result<usize>;
    fn shutdown_write(&mut self) -> std::io::Result<()>;
}

impl InStream for TcpStream {
    fn read_raw(&mut self, buf: &mut [u8]) -> std::io::Result<usize> {
        TcpStream::read(self, buf)
    }
}

impl OutStream for TcpStream {
    fn write_all_raw(&mut self, buf: &[u8]) -> std::io::Result<usize> {
        let mut written = 0;
        while written < buf.len() {
            match TcpStream::write(self, &buf[written..]) {
                Ok(0) => break,
                Ok(n) => written += n,
                Err(e) => return Err(e),
            }
        }
        Ok(written)
    }

    fn shutdown_write(&mut self) -> std::io::Result<()> {
        TcpStream::shutdown(self, Shutdown::Write)
    }
}

impl InStream for ReadHalf {
    fn read_raw(&mut self, buf: &mut [u8]) -> std::io::Result<usize> {
        ReadHalf::read_raw(self, buf)
    }
}

impl OutStream for WriteHalf {
    fn write_all_raw(&mut self, buf: &[u8]) -> std::io::Result<usize> {
        WriteHalf::write_raw(self, buf)
    }

    fn shutdown_write(&mut self) -> std::io::Result<()> {
        WriteHalf::shutdown_write(self)
    }
}

/// Copies from `reader` into `writer` until EOF or an error.
pub fn copy<I: InStream, O: OutStream>(reader: &mut I, writer: &mut O, errs: &ErrSlot) {
    let mut buf = [0u8; 8192];
    loop {
        match reader.read_raw(&mut buf) {
            Ok(0) => {
                if let Err(e) = writer.shutdown_write() {
                    record_error(errs, e);
                }
                return;
            }
            Ok(n) => {
                let mut off = 0usize;
                while off < n {
                    match writer.write_all_raw(&buf[off..n]) {
                        Ok(0) => {
                            record_message(errs, "failed to write whole buffer".to_string());
                            return;
                        }
                        Ok(m) => off += m,
                        Err(e) => {
                            record_error(errs, e);
                            return;
                        }
                    }
                }
            }
            Err(e) => {
                if e.kind() == std::io::ErrorKind::Interrupted {
                    continue;
                }
                record_error(errs, e);
                return;
            }
        }
    }
}
