use clap::{Arg, ArgGroup, Command, error::ErrorKind};
use std::net::IpAddr;

pub struct LocalArgs {
    pub local_port: u16,
    pub local_host: String,
    pub to: String,
    pub port: u16,
    pub secret: Option<String>,
}

pub struct ServerArgs {
    pub min_port: u16,
    pub max_port: u16,
    pub secret: Option<String>,
    pub bind_addr: IpAddr,
    pub bind_tunnels: Option<IpAddr>,
}

pub enum Args {
    Local(LocalArgs),
    Server(ServerArgs),
}

pub const ABOUT: &str = "A modern, simple TCP tunnel in Rust that exposes local ports to a remote server, bypassing standard NAT connection firewalls.";
pub const LOCAL_ABOUT: &str = "Starts a local proxy to the remote server";
pub const SERVER_ABOUT: &str = "Runs the remote proxy server";

const LOCAL_GROUP_USAGE: &str =
    "<LOCAL_PORT|--local-host <HOST>|--to <TO>|--port <PORT>|--secret <SECRET>>";
const SERVER_GROUP_USAGE: &str = "<--min-port <MIN_PORT>|--max-port <MAX_PORT>|--secret <SECRET>|--bind-addr <BIND_ADDR>|--bind-tunnels <BIND_TUNNELS>>";

pub fn bin_name() -> String {
    std::env::args()
        .next()
        .map(|a| {
            std::path::Path::new(&a)
                .file_name()
                .map(|f| f.to_string_lossy().into_owned())
                .unwrap_or_else(|| a.clone())
        })
        .unwrap_or_else(|| "bore".to_string())
}

pub fn build() -> Command {
    let local = Command::new("local")
        .about(LOCAL_ABOUT)
        .group(
            ArgGroup::new("local")
                .multiple(true)
                .args(["local_port", "local_host", "to", "port", "secret"]),
        )
        .arg(
            Arg::new("local_port")
                .value_name("LOCAL_PORT")
                .help("The local port to expose")
                .num_args(1)
                .required(true)
                .value_parser(clap::value_parser!(u16))
                .env("BORE_LOCAL_PORT"),
        )
        .arg(
            Arg::new("local_host")
                .short('l')
                .long("local-host")
                .value_name("HOST")
                .help("The local host to expose")
                .default_value("localhost"),
        )
        .arg(
            Arg::new("to")
                .short('t')
                .long("to")
                .value_name("TO")
                .help("Address of the remote server to expose local ports to")
                .required(true)
                .env("BORE_SERVER"),
        )
        .arg(
            Arg::new("port")
                .short('p')
                .long("port")
                .value_name("PORT")
                .help("Optional port on the remote server to select")
                .default_value("0")
                .value_parser(clap::value_parser!(u16)),
        )
        .arg(
            Arg::new("secret")
                .short('s')
                .long("secret")
                .value_name("SECRET")
                .help("Optional secret for authentication")
                .env("BORE_SECRET")
                .hide_env_values(true),
        );

    let server = Command::new("server")
        .about(SERVER_ABOUT)
        .group(
            ArgGroup::new("server")
                .multiple(true)
                .args(["min_port", "max_port", "secret", "bind_addr", "bind_tunnels"]),
        )
        .arg(
            Arg::new("min_port")
                .long("min-port")
                .value_name("MIN_PORT")
                .help("Minimum accepted TCP port number")
                .default_value("1024")
                .value_parser(clap::value_parser!(u16))
                .env("BORE_MIN_PORT"),
        )
        .arg(
            Arg::new("max_port")
                .long("max-port")
                .value_name("MAX_PORT")
                .help("Maximum accepted TCP port number")
                .default_value("65535")
                .value_parser(clap::value_parser!(u16))
                .env("BORE_MAX_PORT"),
        )
        .arg(
            Arg::new("secret")
                .short('s')
                .long("secret")
                .value_name("SECRET")
                .help("Optional secret for authentication")
                .env("BORE_SECRET")
                .hide_env_values(true),
        )
        .arg(
            Arg::new("bind_addr")
                .long("bind-addr")
                .value_name("BIND_ADDR")
                .help("IP address to bind to, clients must reach this")
                .default_value("0.0.0.0")
                .value_parser(clap::value_parser!(IpAddr)),
        )
        .arg(
            Arg::new("bind_tunnels")
                .long("bind-tunnels")
                .value_name("BIND_TUNNELS")
                .help("IP address where tunnels will listen on, defaults to --bind-addr")
                .value_parser(clap::value_parser!(IpAddr)),
        );

