pub fn bin_name() -> String {
    std::env::args()
        .next()
        .map(|a| {
            std::path::Path::new(&a)
                .file_name()
                .map(|f| f.to_string_lossy().into_owned())
                .unwrap_or_else(|| a.clone())
        })
        .unwrap_or_else(|| "bore".to_string())
}

pub fn build() -> Command {
    let local = Command::new("local")
        .about(LOCAL_ABOUT)
        .group(
            ArgGroup::new("local")
                .multiple(true)
                .args(["local_port", "local_host", "to", "port", "secret"]),
        )
        .arg(
            Arg::new("local_port")
                .value_name("LOCAL_PORT")
                .help("The local port to expose")
                .num_args(1)
                .required(true)
                .value_parser(clap::value_parser!(u16))
                .env("BORE_LOCAL_PORT"),
        )
        .arg(
            Arg::new("local_host")
                .short('l')
                .long("local-host")
                .value_name("HOST")
                .help("The local host to expose")
                .default_value("localhost"),
        )
        .arg(
            Arg::new("to")
                .short('t')
                .long("to")
                .value_name("TO")
                .help("Address of the remote server to expose local ports to")
                .required(true)
                .env("BORE_SERVER"),
        )
        .arg(
            Arg::new("port")
                .short('p')
                .long("port")
                .value_name("PORT")
                .help("Optional port on the remote server to select")
                .default_value("0")
                .value_parser(clap::value_parser!(u16)),
        )
        .arg(
            Arg::new("secret")
                .short('s')
                .long("secret")
                .value_name("SECRET")
                .help("Optional secret for authentication")
                .env("BORE_SECRET")
                .hide_env_values(true),
        );

    let server = Command::new("server")
        .about(SERVER_ABOUT)
        .group(
            ArgGroup::new("server")
                .multiple(true)
                .args(["min_port", "max_port", "secret", "bind_addr", "bind_tunnels"]),
        )
        .arg(
            Arg::new("min_port")
                .long("min-port")
                .value_name("MIN_PORT")
                .help("Minimum accepted TCP port number")
                .default_value("1024")
                .value_parser(clap::value_parser!(u16))
                .env("BORE_MIN_PORT"),
        )
        .arg(
            Arg::new("max_port")
                .long("max-port")
                .value_name("MAX_PORT")
                .help("Maximum accepted TCP port number")
                .default_value("65535")
                .value_parser(clap::value_parser!(u16))
                .env("BORE_MAX_PORT"),
        )
        .arg(
            Arg::new("secret")
                .short('s')
                .long("secret")
                .value_name("SECRET")
                .help("Optional secret for authentication")
                .env("BORE_SECRET")
                .hide_env_values(true),
        )
        .arg(
            Arg::new("bind_addr")
                .long("bind-addr")
                .value_name("BIND_ADDR")
                .help("IP address to bind to, clients must reach this")
                .default_value("0.0.0.0")
                .value_parser(clap::value_parser!(IpAddr)),
        )
        .arg(
            Arg::new("bind_tunnels")
                .long("bind-tunnels")
                .value_name("BIND_TUNNELS")
                .help("IP address where tunnels will listen on, defaults to --bind-addr")
                .value_parser(clap::value_parser!(IpAddr)),
        );

    Command::new("bore-cli")
        .version("0.6.0")
        .about(ABOUT)
        .arg_required_else_help(true)
        .subcommand_required(true)
        .subcommand(local)
        .subcommand(server)
}

/// Reproduces the two differences between clap 4.6 and the version used to
/// build the original binary:
///   * the usage line of "did you mean" errors inside a subcommand shows the
///     argument group instead of the individual arguments,
///   * an unknown subcommand that resembles a real one additionally suggests
///     passing it as a value.
fn patch_error(mut text: String, bin: &str) -> String {
    if text.contains("tip: a similar subcommand exists:") {
        let name = text
            .lines()
            .find(|l| l.starts_with("error: unrecognized subcommand '"))
            .and_then(|l| {
                l.trim_start_matches("error: unrecognized subcommand '")
                    .trim_end_matches('\'')
                    .to_string()
                    .into()
            });
        if let Some(name) = name {
            let tip = format!(
                "  tip: to pass '{}' as a value, use '{} -- {}'\n",
                name, bin, name
            );
            if let Some(pos) = text.find("tip: a similar subcommand exists:") {
                if let Some(line_end) = text[pos..].find('\n') {
                    let insert = pos + line_end + 1;
                    text.insert_str(insert, &tip);
                }
            }
        }
    }
    if text.contains("tip: a similar argument exists:") {
        for line in text.lines().collect::<Vec<_>>() {
            if line.starts_with("Usage: ") {
                let rest = line.trim_start_matches("Usage: ");
                if let Some(sub) = rest.strip_prefix(&format!("{} ", bin)) {
                    let replacement = if sub.starts_with("local ") || sub == "local" {
                        Some(LOCAL_GROUP_USAGE)
                    } else if sub.starts_with("server ") || sub == "server" {
                        Some(SERVER_GROUP_USAGE)
                    } else {
                        None
                    };
                    if let Some(group) = replacement {
                        let sub_name = sub.split(' ').next().unwrap_or(sub);
                        let new_usage = format!("Usage: {} {} {}", bin, sub_name, group);
                        text = text.replace(line, &new_usage);
                    }
                }
                break;
            }
        }
    }
    text
}

pub fn parse() -> Args {
    let bin = bin_name();
    let mut cmd = build();
    let matches = match cmd.try_get_matches() {
        Ok(m) => m,
        Err(e) => {
            match e.kind() {
                ErrorKind::DisplayHelp | ErrorKind::DisplayVersion => {
                    let _ = e.print();
                    std::process::exit(0);
                }
                _ => {
                    let text = patch_error(e.to_string(), &bin);
                    eprint!("{}", text);
                    std::process::exit(2);
                }
            }
        }
    };

    match matches.subcommand() {
        Some(("local", m)) => Args::Local(LocalArgs {
            local_port: *m.get_one::<u16>("local_port").unwrap(),
            local_host: m.get_one::<String>("local_host").unwrap().clone(),
            to: m.get_one::<String>("to").unwrap().clone(),
            port: *m.get_one::<u16>("port").unwrap(),
            secret: m.get_one::<String>("secret").cloned(),
        }),
        Some(("server", m)) => Args::Server(ServerArgs {
            min_port: *m.get_one::<u16>("min_port").unwrap(),
            max_port: *m.get_one::<u16>("max_port").unwrap(),
            secret: m.get_one::<String>("secret").cloned(),
            bind_addr: *m.get_one::<IpAddr>("bind_addr").unwrap(),
            bind_tunnels: m.get_one::<IpAddr>("bind_tunnels").copied(),
        }),
        _ => {
            let _ = cmd.print_help();
            std::process::exit(2);
        }
    }
}

/// Emits the "port range is empty" error exactly like the original does (the
/// usage line refers to the crate name rather than the executed binary).
pub fn port_range_is_empty() -> ! {
    let cmd = build();
    let e = cmd.error(ErrorKind::InvalidValue, "port range is empty");
    e.exit()
}
