// minimal reproduction of the message parsing
use serde::{Deserialize, Serialize};
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Uuid(pub [u8;16]);
impl<'de> Deserialize<'de> for Uuid {
    fn deserialize<D: serde::Deserializer<'de>>(d: D) -> Result<Uuid, D::Error> {
        let s = String::deserialize(d)?;
        let mut out=[0u8;16]; let mut idx=0; let mut hi: Option<u8>=None;
        for c in s.chars() { if c=='-' {continue} let v=c.to_digit(16).ok_or(serde::de::Error::custom("bad"))? as u8; match hi { None=>hi=Some(v), Some(h)=>{ if idx>=16 {return Err(serde::de::Error::custom("bad"))} out[idx]=(h<<4)|v; idx+=1; hi=None; } } }
        if idx==16 && hi.is_none() { Ok(Uuid(out)) } else { Err(serde::de::Error::custom("bad")) }
    }
}
impl Serialize for Uuid { fn serialize<S: serde::Serializer>(&self, s:S)->Result<S::Ok,S::Error>{ s.serialize_str(&format!("{:?}", self)) } }
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub enum ClientMessage { Hello(u16), Authenticate(String), Accept(Uuid) }
fn main(){
    for s in [b"{\"Bogus\":1}\x00".as_slice(), b"{}\x00", b"{\"Hello\":26101}\x00", b"{\"Hello\":-1}\x00", b"\x00"] {
        let f: Vec<u8> = s.iter().cloned().filter(|b| *b!=0).collect();
        let r: Result<Option<ClientMessage>, _> = serde_json::from_slice(&f).map(Some);
        println!("{:?} -> {:?}", String::from_utf8_lossy(&f), r.map_err(|e| e.to_string()));
    }
}
EOF
